const item = $input.first();
const body = item.json.body || item.json || {};
const headers = item.json.headers || {};

const expectedSecret = 'uigfbwejbCHNRwjrwehrbcvHBWEVENVEKEWVBJWE';
const providedSecret = headers['x-pattern-helper-secret'] || headers['X-Pattern-Helper-Secret'] || body.secret || '';

if (expectedSecret && providedSecret !== expectedSecret) {
  return [{ json: { ok: false, statusCode: 401, error: 'Unauthorised request.' } }];
}

const action = String(body.action || '').trim().toLowerCase();
const question = String(body.question || body.message || '').trim();
const sessionId = String(body.session_id || body.sessionId || body.session || '').trim() || `session_${Date.now()}`;
const skillLevel = String(body.skill_level || body.skillLevel || 'beginner').trim().toLowerCase();
const clientHistory = Array.isArray(body.history) ? body.history.slice(-8) : [];
const toolMode = String(body.tool_mode || '').trim();
const imageDataUri = String(body.image_data_uri || '');
const mimeType = String(body.mime_type || 'image/jpeg');
const originalFilename = String(body.original_filename || 'stitch-photo');
const requestedModel = String(body.model || '').trim();
const projectId = String(body.project_id || body.projectId || '').trim();
const fileId = String(body.file_id || body.fileId || '').trim();
const jobId = String(body.job_id || body.jobId || '').trim();
const answerMode = String(body.answer_mode || body.answerMode || '').trim();
const patternId = String(body.pattern_id || body.patternId || '').trim();
const workflowUserId = String(body.user_id || body.userId || '').trim();
const platformUserId = String(body.platform_user_id || body.platformUserId || '').trim();
const patternAvailable = body.pattern_available === undefined ? undefined : Boolean(body.pattern_available);
const uploadedPatternTitle = String(body.uploaded_pattern_title || '').trim();
const uploadedPatternSummary = String(body.uploaded_pattern_summary || '').trim();
const patternSummaryText = String(body.pattern_summary_text || '').trim();
const patternSummaryHtml = String(body.pattern_summary_html || '').trim();
const patternSummaryStructured = body.pattern_summary_structured ?? undefined;
const patternMetadata = body.pattern_metadata ?? undefined;
const patternSource = String(body.pattern_source || '').trim();
const patternInstructionText = String(body.pattern_instruction_text || body.patternInstructionText || '').trim();
const patternInstructionPrompt = String(body.pattern_instruction_prompt || body.patternInstructionPrompt || '').trim();
const patternInstructionContextStatus = String(body.pattern_instruction_context_status || body.patternInstructionContextStatus || '').trim();
const patternContextMode = String(body.pattern_context_mode || body.patternContextMode || '').trim();
const responseLanguage = String(body.response_language || '').trim();
const targetLanguage = String(body.target_language || '').trim();
const translationTargetLanguage = String(body.translation_target_language || '').trim();
const locale = String(body.locale || '').trim();
const systemInstruction = String(body.system_instruction || '').trim();

if (action === 'reset') {
  return [{ json: { ok: true, action: 'reset', session_id: sessionId, requested_at: new Date().toISOString() } }];
}

if (!question && !imageDataUri) {
  return [{ json: { ok: false, statusCode: 400, error: 'Please enter a question or upload a photo.' } }];
}

if (question.length > 1200) {
  return [{ json: { ok: false, statusCode: 400, error: 'Please keep questions under 1,200 characters.' } }];
}

return [{
  json: {
    ok: true,
    action: 'chat',
    question,
    session_id: sessionId,
    skill_level: ['beginner','intermediate','advanced'].includes(skillLevel) ? skillLevel : 'beginner',
    client_history: clientHistory,
    tool_mode: toolMode || undefined,
    image_data_uri: imageDataUri || undefined,
    mime_type: mimeType || undefined,
    original_filename: originalFilename || undefined,
    model: requestedModel || undefined,
    project_id: projectId || undefined,
    file_id: fileId || undefined,
    job_id: jobId || undefined,
    answer_mode: answerMode || undefined,
    pattern_id: patternId || undefined,
    user_id: workflowUserId || undefined,
    platform_user_id: platformUserId || undefined,
    pattern_available: patternAvailable,
    uploaded_pattern_title: uploadedPatternTitle || undefined,
    uploaded_pattern_summary: uploadedPatternSummary || undefined,
    pattern_summary_text: patternSummaryText || undefined,
    pattern_summary_html: patternSummaryHtml || undefined,
    pattern_summary_structured: patternSummaryStructured,
    pattern_metadata: patternMetadata,
    pattern_source: patternSource || undefined,
    pattern_instruction_text: patternInstructionText || undefined,
    pattern_instruction_prompt: patternInstructionPrompt || undefined,
    pattern_instruction_context_status: patternInstructionContextStatus || undefined,
    pattern_context_mode: patternContextMode || undefined,
    response_language: responseLanguage || undefined,
    target_language: targetLanguage || undefined,
    translation_target_language: translationTargetLanguage || undefined,
    locale: locale || undefined,
    system_instruction: systemInstruction || undefined,
    redis_key: `stitchsense:chat:${sessionId}`,
    requested_at: new Date().toISOString()
  }
}];

const req = $('Validate Request').first().json;

// Redis is bypassed in this fixed version because the native n8n Redis credential
// connection was failing even though raw AUTH/PING works from inside the n8n container.
// This keeps the chat API working by using client-provided history only.

const clientHistory = Array.isArray(req.client_history) ? req.client_history : [];

const memory = clientHistory
  .filter(m => m && m.role && m.content)
  .slice(-10);

return [{ json: { ...req, memory } }];

const embedding = $json.embedding;
if (!embedding || !Array.isArray(embedding)) {
  throw new Error(`No embedding returned. Response: ${JSON.stringify($json)}`);
}
const req = $('Prepare Memory').first().json;

const isStepGuide = req.tool_mode === 'pattern_step_guide';
const isSummary = req.tool_mode === 'pattern_summary';
const patternPriority = req.answer_mode === 'pattern_priority';

function buildScopeFilter() {
  if (req.project_id) {
    return {
      must: [{
        key: 'project_id',
        match: { value: req.project_id }
      }]
    };
  }

  if (req.file_id) {
    return {
      must: [{
        key: 'file_id',
        match: { value: req.file_id }
      }]
    };
  }

  if (req.job_id) {
    return {
      must: [{
        key: 'job_id',
        match: { value: req.job_id }
      }]
    };
  }

  if (patternPriority) {
    return {
      must: [{
        key: 'project_id',
        match: { value: '__no_pattern_scope_available__' }
      }]
    };
  }

  return null;
}

const scopeFilter = buildScopeFilter();
const hasPatternScope = Boolean(req.project_id || req.file_id || req.job_id);

let qdrant_limit = 8;
let score_threshold = 0.25;
let body = {
  vector: embedding,
  limit: qdrant_limit,
  score_threshold: score_threshold,
  with_payload: true,
  with_vector: false
};

if (scopeFilter) {
  qdrant_limit = (isStepGuide || isSummary) ? 200 : 40;
  body = {
    vector: embedding,
    limit: qdrant_limit,
    with_payload: true,
    with_vector: false,
    filter: scopeFilter
  };
}

const results = [];
results.push({ json: { ...req, embedding, search_body: JSON.stringify(body), qdrant_limit, score_threshold: body.score_threshold || 0, _scroll: false, _scroll_body: null, is_step_guide: isStepGuide, has_pattern_scope: hasPatternScope, scope_filter: scopeFilter } });

if (isStepGuide && scopeFilter) {
  const scrollBody = {
    filter: scopeFilter,
    limit: 200,
    with_payload: true,
    with_vector: false
  };
  results.push({ json: { ...req, embedding, search_body: JSON.stringify(body), qdrant_limit, score_threshold: 0, _scroll: true, _scroll_body: scrollBody, is_step_guide: true, has_pattern_scope: hasPatternScope, scope_filter: scopeFilter } });
}

return results;

const req = $('Prepare Qdrant Search').first().json;

// Stitch Camera mode — build a vision-model payload instead of RAG
if (req.tool_mode === 'stitch_image_analysis' && req.image_data_uri) {
  const visionPrompt = [
    'You are StitchSense, a calm, practical knitting and crochet assistant for a UK WordPress website.',
    '',
    'What to do:',
    '- Look at the uploaded photo carefully and describe what the visitor has made.',
    '- Identify the craft type: knitting, crochet, or unsure.',
    '- Identify the likely stitch or technique if you can see it.',
    '- Describe any visible texture, pattern or colour work.',
    '- Check for common issues: twisted stitches, dropped stitch, missed yarn over, uneven tension, accidental increase or decrease, wrong-side/right-side confusion, crochet stitch height mismatch, gaps, holes, curling, laddering.',
    '- If the visitor asked a specific question about the photo, answer it directly.',
    '- Give a practical next step or action the visitor can take.',
    '- If the image quality is poor, say so politely and ask for a clearer photo.',
    '',
    'Language and measurement rules:',
    '- Always use British English spelling, grammar and terminology.',
    '- Always default to UK metric measurements: millimetres, centimetres, metres, grams.',
    '- For needles and hooks, default to UK/EU metric sizing in millimetres.',
    '- If you mention US terms, explicitly give the UK equivalent.',
    '',
    'Style rules:',
    '- Be honest about uncertainty. Never pretend to see what is not visible.',
    '- Use plain, friendly UK English.',
    '- Use short sections with clear headings.',
    '- Tailor the LANGUAGE complexity to the visitor skill level (' + (req.skill_level || 'beginner') + '). Use simpler words and sentences for beginners, more technical terminology for advanced knitters. NEVER hide, remove, or refuse to provide complex pattern instructions based on skill level — always include the full instructions regardless of declared skill level.',
    '- Never mention AI, models, prompts, n8n, OpenRouter, tokens or backend systems.',
    '- Do not invent stitch counts, yarn brands or book titles.',
    ''
  ].join('\n');

  const questionText = req.question || 'What stitch, technique or issue can you see in this photo?';

  const visionPayload = {
    model: req.model || req.requested_model || 'google/gemini-2.5-flash',
    messages: [
      { role: 'system', content: visionPrompt },
      { role: 'user', content: [
        { type: 'image_url', image_url: { url: req.image_data_uri } },
        { type: 'text', text: questionText }
      ]}
    ],
    temperature: 0.3,
    max_tokens: 900
  };

  return [{
    json: {
      ...req,
      sources: [],
      context_count: 0,
      openrouter_payload: visionPayload,
      model: req.model || req.requested_model || 'google/gemini-2.5-flash'
    }
  }];
}

const patternInstructionText = String(req.pattern_instruction_text || '').trim();
const patternPriority = req.answer_mode === 'pattern_priority' || req.answer_mode === 'pattern_instruction_text' || Boolean(patternInstructionText);
const allItems = $input.all();
const seen = new Set();
const sources = [];
const contextBlocks = [];

for (const item of allItems) {
  const json = item.json;
  const isScroll = json._scroll === true;

  let hits = [];
  if (isScroll) {
    const points = (json.result && json.result.points) ? json.result.points : [];
    hits = points.map(p => ({ payload: p.payload || {}, chunk_index: (p.payload || {}).chunk_index }));
  } else {
    hits = Array.isArray(json.result) ? json.result : [];
  }

  const minScore = patternPriority ? -1.0 : Number(req.score_threshold || 0.25);

  for (const hit of hits) {
    if (!hit) continue;
    if (!isScroll && typeof hit.score === 'number' && hit.score < minScore) continue;

    const payload = hit.payload || {};
    const content = String(payload.content || '').trim();
    if (!content) continue;

    const chunkIndex = payload.chunk_index ?? 0;
    const key = `${payload.project_id || payload.file_id || payload.job_id || payload.title || 'Untitled'}::${chunkIndex}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const source = {
      title: payload.title || req.uploaded_pattern_title || 'Selected pattern source',
      url: payload.url || '',
      drive_link: payload.drive_link || '',
      chunk_index: chunkIndex,
      score: isScroll ? null : (hit.score ?? null)
    };
    sources.push(source);
    contextBlocks.push({ index: chunkIndex, text: [
      `CHUNK ${chunkIndex}`,
      content
    ].join('\n') });
  }
}

contextBlocks.sort((a, b) => a.index - b.index);
const context = contextBlocks.map(b => b.text).join('\n\n---\n\n');

const memoryText = (Array.isArray(req.memory) ? req.memory : [])
  .slice(-8)
  .map(m => `${m.role === 'assistant' ? 'Assistant' : 'Visitor'}: ${String(m.content || '').slice(0, 800)}`)
  .join('\n');

const isStepGuide = req.tool_mode === 'pattern_step_guide';
const hasInlineInstructionText = Boolean(patternInstructionText);
const chunkCount = contextBlocks.length + (hasInlineInstructionText ? 1 : 0);
const patternSummaryFallback = [
  req.uploaded_pattern_summary,
  req.pattern_summary_text,
  req.pattern_summary_html,
  req.pattern_summary_structured ? JSON.stringify(req.pattern_summary_structured) : '',
  req.pattern_metadata ? JSON.stringify(req.pattern_metadata) : ''
].filter(Boolean).join('\n\n');
const hasScopedPatternContext = Boolean(req.project_id || req.file_id || req.job_id);
const usingPatternSummaryFallback = patternPriority && sources.length === 0 && Boolean(patternSummaryFallback);

const stepGuidePreamble = isStepGuide
  ? `\nCRITICAL: Use the selected pattern context below as primary evidence. If extracted uploaded PDF text is present, it is more authoritative than vector search chunks or summaries. Read through ALL supplied pattern text carefully. Do NOT say you only have a summary or that you need more information when row/round instructions are present. Your job is to expand the instructions into a fully written-out, stitch-by-stitch, row-by-row guide. Never use "rep Row X" or "rep from *" — write every row in full.\n`
  : '';

const patternNotFoundWarning = (patternPriority && !hasInlineInstructionText && !usingPatternSummaryFallback && sources.length === 0)
  ? '\nCRITICAL: This request is for one selected pattern only. If the selected pattern text is missing, do NOT use any other pattern knowledge and do NOT guess. Politely say that the selected pattern content was not available and ask the visitor to re-upload or re-import that exact pattern.\n'
  : '';

const systemPrompt = [
  'You are StitchSense, a calm, practical knitting and crochet assistant for a WordPress website based in the United Kingdom.',
  '',
  'Language and measurement rules:',
  '- Always use British English spelling, grammar and terminology.',
  '- Never default to American English spellings, wording or measurements.',
  '- Always default to UK metric measurements where relevant: millimetres, centimetres, metres, grams and kilograms.',
  '- For knitting needles and crochet hooks, default to UK/EU metric sizing in millimetres, such as 4 mm, 5 mm or 6.5 mm.',
  '- For yarn quantities, default to grams rather than ounces.',
  '- For lengths, default to centimetres or metres rather than inches or yards.',
  '- Only mention imperial measurements if the visitor specifically asks for them or if converting a US pattern.',
  '- If the source material uses US or imperial terms, explain them in UK-friendly metric terms.',
  '- If stitch terminology could be US or UK crochet terminology, clearly explain the UK equivalent without being patronising.',
  '',
  'Style rules:',
  '- Use plain, natural UK English.',
  '- Keep answers friendly, practical and easy to follow.',
  '- Do not use LaTeX, formula blocks or raw markdown asterisks.',
  '- Use short sections, short paragraphs and clear numbered steps when useful.',
  '- Make maths readable with worked examples rather than abstract formulas.',
  '- Never mention Qdrant, embeddings, RAG, n8n, prompts or vector databases.',
  '- Do not invent pattern instructions, stitch counts, yarn weights, book titles, page numbers or citations.',
  '- If the context is weak, say what you can infer generally and ask one useful follow-up question.',
  '- When the visitor asks for a step-by-step row-by-row guide or a pattern rewrite, you MUST fully expand every instruction. Never use "rep Row X" or "rep from *". Write out every single row in full, stitch by stitch. Replace every abbreviation reference with the complete stitch-by-stitch text. The reader must be able to follow the guide without needing to look up rows in other parts of the pattern. This is NOT optional.',
  '- Tailor the LANGUAGE complexity to the visitor skill level (' + (req.skill_level || 'beginner') + '). Use simpler words and sentences for beginners, more technical terminology for advanced knitters. NEVER hide, remove, or refuse to provide complex pattern instructions based on skill level — always include the full instructions regardless of declared skill level.',
  '- If answer_mode is pattern_priority or pattern_instruction_text, use only the selected pattern context supplied in this request. Never pull instructions, titles, stitch counts, sizes, yarn details, or summaries from any other pattern.',
  '- General knitting knowledge may help explain techniques, but it must never replace or override the selected pattern context.',
  stepGuidePreamble,
  patternNotFoundWarning,
  req.system_instruction || ''
].filter(Boolean).join('\n');

const selectedPatternContextText = hasInlineInstructionText
  ? `Extracted uploaded PDF instruction text from the selected pattern. Treat this as the primary source for row-by-row and step-by-step requests.\n${req.pattern_instruction_prompt || ''}\n\n${patternInstructionText}`
  : (usingPatternSummaryFallback
      ? `Selected pattern fallback context:\n${patternSummaryFallback}`
      : (context || (patternPriority
          ? 'The selected pattern content was not available. Do not answer using any other pattern. Ask the visitor to re-upload or re-import the selected pattern.'
          : 'No strong matching context was found.')));

const userPrompt = [
  `Visitor skill level: ${req.skill_level}`,
  patternPriority ? `Selected pattern title: ${req.uploaded_pattern_title || 'Unknown pattern'}` : '',
  patternPriority ? `Pattern source: ${req.pattern_source || 'Unknown source'}` : '',
  patternPriority ? `Scoped retrieval available: ${hasScopedPatternContext ? 'yes' : 'no'}` : '',
  '',
  'Recent conversation:',
  memoryText || 'No previous messages.',
  '',
  'Visitor question:',
  req.question,
  '',
  patternPriority ? 'Selected pattern context:' : 'Knowledge-base context:',
  selectedPatternContextText,
  '',
  'Return only the helpful answer. Do not include visible source links.'
].filter(Boolean).join('\n');

const stepGuideModel = 'google/gemini-2.5-flash';
const defaultModel = req.model || req.requested_model || 'qwen/qwen-2.5-72b-instruct';

const payload = {
  model: isStepGuide ? stepGuideModel : defaultModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  temperature: 0.3,
  max_tokens: (isStepGuide || req.tool_mode === 'pattern_rewrite' || req.tool_mode === 'pattern_summary') ? 12000 : 700
};

return [{
  json: {
    ...req,
    sources,
    context_count: sources.length,
    openrouter_payload: payload,
    model: isStepGuide ? stepGuideModel : defaultModel,
    using_pattern_summary_fallback: usingPatternSummaryFallback,
    using_inline_instruction_text: hasInlineInstructionText,
    has_scoped_pattern_context: hasScopedPatternContext
  }
}];

const rag = $('Build RAG Prompt').first().json;
let answer = '';

if (Array.isArray($json.choices) && $json.choices[0]?.message?.content) {
  answer = String($json.choices[0].message.content).trim();
} else if ($json.output) {
  answer = String($json.output).trim();
} else if ($json.text) {
  answer = String($json.text).trim();
}

if (!answer) {
  answer = 'Sorry, I could not generate a useful answer this time. Please try rewording the question or uploading a clearer photo.';
}

while (answer.includes('\n\n\n')) {
  answer = answer.replace('\n\n\n', '\n\n');
}

answer = answer.trim();

const previous = Array.isArray(rag.memory) ? rag.memory : [];
const updatedMemory = [
  ...previous,
  { role: 'user', content: rag.question || '(image sent)', at: rag.requested_at },
  { role: 'assistant', content: answer, at: new Date().toISOString() }
].slice(-12);

const modelName = rag.model || 'qwen/qwen-2.5-72b-instruct';

return [{
  json: {
    success: true,
    provider: 'openrouter',
    model: modelName,
    answer,
    sources: [],
    context_count: rag.context_count,
    session_id: rag.session_id,
    redis_key: rag.redis_key,
    memory_json: JSON.stringify(updatedMemory),
    answered_at: new Date().toISOString()
  }
}];
